referenceSolutions.javascript:
export function solve(arrays, key) {
  const seen = new Set();
  const out = [];
  for (const rows of arrays)
    for (const row of rows)
      if (!seen.has(row[key])) {
        seen.add(row[key]);
        out.push(row);
      }
  return out;
}

